/* From Uiverse.io by Praashoo7  - Tags: blue, loading, loader, smooth, text animation, wave, loading animation */
.__UIV_SCOPE__ .load {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30em;
  height: 12em;
  margin-left: -1em;
}

.__UIV_SCOPE__ .loader {
  width: 2.25em;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
}

.__UIV_SCOPE__ .loader .l {
  position: absolute;
  margin-top: -2em;
  font-size: 4em;
  color: white;
  text-shadow: 5px 0px 1px #000, 1px 1px 0 #000, 1px -1px 0 #000,
    -1px -1px 0 #000;
  animation: 2s float infinite ease-in-out;
}

.__UIV_SCOPE__ .loader:nth-child(1) .l:nth-child(1) {
  animation-delay: 0.4s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(1) .l:nth-child(2) {
  animation-delay: 0.3s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(1) .l:nth-child(3) {
  animation-delay: 0.2s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(1) .l:nth-child(4) {
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .loader:nth-child(2) .l:nth-child(1) {
  animation-delay: 0.5s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(2) .l:nth-child(2) {
  animation-delay: 0.4s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(2) .l:nth-child(3) {
  animation-delay: 0.3s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(2) .l:nth-child(4) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .loader:nth-child(3) .l:nth-child(1) {
  animation-delay: 0.6s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(3) .l:nth-child(2) {
  animation-delay: 0.5s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(3) .l:nth-child(3) {
  animation-delay: 0.4s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(3) .l:nth-child(4) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader:nth-child(4) .l:nth-child(1) {
  animation-delay: 0.7s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(4) .l:nth-child(2) {
  animation-delay: 0.6s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(4) .l:nth-child(3) {
  animation-delay: 0.5s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(4) .l:nth-child(4) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .loader:nth-child(5) .l:nth-child(1) {
  animation-delay: 0.8s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(5) .l:nth-child(2) {
  animation-delay: 0.7s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(5) .l:nth-child(3) {
  animation-delay: 0.6s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(5) .l:nth-child(4) {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .loader:nth-child(6) .l:nth-child(1) {
  animation-delay: 0.9s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(6) .l:nth-child(2) {
  animation-delay: 0.8s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(6) .l:nth-child(3) {
  animation-delay: 0.7s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(6) .l:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader:nth-child(7) .l:nth-child(1) {
  animation-delay: 1s;
  margin-left: 0.3em;
  color: #105ee8;
}
.__UIV_SCOPE__ .loader:nth-child(7) .l:nth-child(2) {
  animation-delay: 0.9s;
  margin-left: 0.2em;
  color: #579dff;
}
.__UIV_SCOPE__ .loader:nth-child(7) .l:nth-child(3) {
  animation-delay: 0.8s;
  margin-left: 0.1em;
  color: #acd9f1;
}
.__UIV_SCOPE__ .loader:nth-child(7) .l:nth-child(4) {
  animation-delay: 0.7s;
}

@keyframes float {
  0% {
    transform: translateY(0em);
  }
  50% {
    transform: translateY(2em);
  }
  100% {
    transform: translateY(0em);
  }
}
